data.command:
/bin/bash -lc 'unset GIT_INDEX_FILE
before=$("$HORIZON_GIT" rev-parse HEAD)
result=$(
  "$HORIZON_GIT" diff --cached --name-status HEAD |
  awk -F '"'\\t' '"'$1 ~ /''^D/ { print $2 }'"' |
  perl -lne '
    "'$total++;
    $lean++ if /'"\\.lean\\z/;
    if (-e "'$_ || -l $_) { $present++ } else { $missing++; push @missing, $_ }
    END {
      print "__DISK_CHECK__:present=" . ($present+0) . ":missing=" . ($missing+0) .
        ":total=" . ($total+0) . ":lean=" . ($lean+0);
      print "MISSING_PATH:$_" for @missing;
    }
  '"'
)
after="'$("$HORIZON_GIT" rev-parse HEAD)
printf "head_before=%s'"\\nhead_after=%s\\n%s\\n\" \""'$before" "$after" "$result"'

/bin/bash -lc 'unset GIT_INDEX_FILE
before=$("$HORIZON_GIT" rev-parse HEAD)
result=$(
  "$HORIZON_GIT" diff --cached --name-status HEAD |
  awk -F '"'\\t' '
  {
    total++
    s="'$1
    if (s ~ /''^A/) a++
    else if (s ~ /''^M/) m++
    else if (s ~ /''^D/) { d++; print "HEAD:" $2 }
    else if (s ~ /''^[RC]/) r++
    else o++
  }
  END { print "__SUMMARY__:" total+0 ":" a+0 ":" m+0 ":" d+0 ":" r+0 ":" o+0 }
  '"' |
  \""'$HORIZON_GIT" cat-file --batch-check='"'%(objectname)' |
  awk '
  /"'^__SUMMARY__:/ {
    sub(/ missing$/, "")
    summary=$0
    next
  }
  / missing$/ { missing++; next }
  { present++ }
  END {
    print summary
    printf "__HEAD_CHECK__:present=%d:missing=%d:total=%d'"\\n\", present+0, missing+0, present+missing
  }
  '
)
after="'$("$HORIZON_GIT" rev-parse HEAD)
printf "head_before=%s'"\\nhead_after=%s\\n%s\\n\" \""'$before" "$after" "$result"'

