/bin/bash -lc "unset GIT_INDEX_FILE
awk '
FNR == NR { wanted["'$0]=1; total++; next }
($0 in wanted) { present[$0]=1 }
END {
  for (p in wanted) if (!(p in present)) { missing++; print "MISSING_HEAD:" p }
  printf "head_tree present=%d missing=%d total=%d'"\\n\", total-missing, missing+0, total
}
